import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{newProject,validateProject}from'../dist/model.js';import{generateSettlement}from'../dist/settlement-generator.js';import{movementAt}from'../dist/world-model.js';import{MASKS}from'../dist/smart-model.js';
const library=JSON.parse(fs.readFileSync(new URL('../dist/assets/settlements/library.json',import.meta.url))),assets=JSON.parse(fs.readFileSync(new URL('../dist/assets/smart-catalog.json',import.meta.url))).assets;globalThis.fetch=async url=>({ok:true,json:async()=>JSON.parse(fs.readFileSync(new URL('../dist/'+url,import.meta.url)))});
function walk(map,start){const seen=new Set(),todo=[start];while(todo.length){const i=todo.pop(),x=i%map.width,y=Math.floor(i/map.width);if(x<0||y<0||x>=map.width||y>=map.height||seen.has(i)||movementAt(map,x,y).collision)continue;seen.add(i);if(x)todo.push(i-1);if(x<map.width-1)todo.push(i+1);todo.push(i-map.width,i+map.width);}return seen;}
test('Every included source and requested facility works without source ROM files',()=>{assert.equal(library.profiles.length,7);for(const p of library.profiles)assert(library.templates.some(t=>t.profileId===p.id&&t.kind==='house'));for(const kind of ['centre','mart','gym','game-corner','department-store','cave'])assert(library.templates.some(t=>t.kind===kind));for(const a of library.assets)assert(fs.existsSync(new URL('../dist/'+a.src,import.meta.url)));});
test('The Emerald path centre and four edges use distinct reviewed native tiles',()=>{const kit=library.profiles.find(p=>p.id==='extended').terrain;assert.equal(kit.roles.center.tile,0x121);assert.equal(kit.roles.e.tile,0x122);assert.equal(kit.roles.n.tile,0x119);assert.equal(new Set(['center','n','e','s','w'].map(k=>kit.roles[k].tile)).size,5);});
test('All seven sources can be mixed with every facility in a portable three-plane map',async()=>{const p=newProject();p.maps=[];const reader={engine:'rse',metatileLayers:3,maps:[{key:'0.0',type:1}],byKey:()=>null},result=await generateSettlement(p,reader,'test-source',library.profiles[0],{seed:42,preset:'meadow-village',styles:library.profiles.map(p=>p.id),facilities:['centre','mart','gym','game-corner','department-store','cave'],interiors:false});Object.assign(p,{maps:result.maps,assets:result.assets,romObjects:result.templates,links:result.links,activeMapId:result.maps[0].id});validateProject(p,assets);assert(result.templates.every(t=>t.layerCount===3&&t.overlay.planeAssetIds.length===3));assert.equal(result.maps[0].generator.styles.length,7);});
test('Caverns retain reachable doorways and exits across twenty seeds',async()=>{for(let seed=0;seed<20;seed++){const p=newProject();p.maps=[];const result=await generateSettlement(p,null,null,library.profiles[1],{seed,preset:'underground-village',styles:['firered','extended','other'],facilities:['centre','mart','gym','game-corner','department-store','cave'],interiors:true}),m=result.maps[0],e=m.generator.exits[0],seen=walk(m,e.y*m.width+e.x);assert(m.generator.cave.solidCells>m.width*m.height*.1);for(const a of m.nativeAssemblies.filter(a=>a.interiorId)){const e=a.entrances[0];assert(seen.has((a.y+e.y)*m.width+a.x+e.x),a.name+' seed '+seed);}for(const e of m.generator.exits)assert(seen.has(e.y*m.width+e.x));assert.equal(m.rom.mapType,4);assert(m.generator.layoutSample);}});

test('Every bundled entrance has a walkable approach through its complete footprint',()=>{for(const t of library.templates)for(const e of t.entrances||[])for(let y=e.y;y<t.h;y++)assert.equal(t.rules[y*t.w+e.x].collision,0,t.name+' doorway');});

test('Underground uses filled wall terrain, quiet dirt and optional blocking boulders',async()=>{for(const rocks of[true,false]){const p=newProject();p.maps=[];const r=await generateSettlement(p,null,null,library.profiles[1],{seed:42,preset:'underground-village',facilities:['centre','mart','gym'],features:{rocks},interiors:false}),m=r.maps[0];assert.equal(m.generator.cave.version,2);assert(m.layers.ground.some(t=>t?.a===library.cave.wallAssetId&&t.terrain===library.cave.wallTerrainId));assert(m.layers.ground.some(t=>t?.a===library.cave.floorAssetId));assert(!m.layers.ground.some(t=>t?.a===library.cave.assetId));const b=m.objects.filter(o=>library.cave.rocks.some(r=>r.assetId===o.assetId));assert.equal(b.length>0,rocks);for(const o of b)assert.equal(movementAt(m,o.x,o.y).collision,1);}});
